eturn(res)<br>+}<br>+<br>+##################<br>+###One thresholds<br>+##################<br>+<br> IDS&lt;-as.matrix(expand.grid(thDelay, gammas))<br>-result &lt;- apply(IDS, 1, SSRestim)<br>-SSRthresh&lt;-min(result)<br>+result &lt;- apply(IDS, 1, SSRestim,yy=yy, xxl=xxl,xxh=xxh,z=z)#<br>+bestDelay&lt;-IDS[which.min(result),1]<br>+bestThresh&lt;-IDS[which.min(result),2]<br>+cat(&quot;Best unique threshold&quot;, bestThresh, &quot;				 SSR&quot;, min(result), &quot;
