br>+bootstraploop&lt;-function(x, thVar=NULL){<br>+<br>+xboot&lt;-round(bootModel(x=x),6)<br>+<br>+# SSR of linear boot model<br>+string&lt;-embed(xboot,m+1)<br>+stringxx&lt;-string[,-1]<br>+xxb&lt;-cbind(1,stringxx)<br>+yyb &lt;- string[,1]<br>  <br>SSRb&lt;-crossprod(yyb-xxb%*%chol2inv(chol(crossprod(xxb)))%*%crossprod(xxb,yyb)) #SSR<p>-#SSR for threshold model<br>-xxl &lt;- cbind(1, xxb[, seq_len(mL)])<br>-xxh &lt;- cbind(1, xxb[, seq_len(mH)])<br>-<br>-if(!missing(thVar)) z&lt;-zext<br>-else z&lt;-xxb[round(trim*ng):round((1-trim)*ng)]<br>-<br>-gammas&lt;-sort(unique(z[,1]))	#Treshold values<br>-IDSb&lt;-as.matrix(expand.grid(thDelay, gammas))			#Combinations of <br>thresold and delays<br>-store&lt;-apply(IDSb, 1, SSRestim )				#Minimal SSR<br>-print(store)<br>-SSRthreshb&lt;-min(store)<br>+<br>+#SSR for threshold boot model<br>+xxlb &lt;- cbind(1, stringxx[, seq_len(mL)])<br>+xxhb &lt;- cbind(1, stringxx[, seq_len(mH)])<br>+<br>+if(!is.null(thVar)) zb&lt;-as.matrix(zext)<br>+else zb&lt;-as.matrix(stringxx[, seq_len(max(thDelay)+1)])<br>+<br>+allgammasb&lt;-sort(unique(zb[,b]))<br>+ng&lt;-length(allgammasb)<br>+gammasb&lt;-allgammasb[(ceiling(trim*ng)+1):floor((1-trim)*ng-1)]<br>+<br>+<br>+###Search<br>+IDSb&lt;-as.matrix(expand.grid(thDelay, gammasb))			#Combinations of <br>thresold and delays<br>+storeb&lt;-apply(IDSb, 1, SSRestim,yy=yyb,xxl=xxlb,xxh=xxhb,z=zb)				<br>#Minimal SSR<br>+SSR1threshb&lt;-min(storeb, na.rm=TRUE)<br>+<br>+<br>+#two thresh model<br>+bestDelayb&lt;-IDSb[which.min(storeb),1]<br>+bestThreshb&lt;-IDSb[which.min(storeb),2]<br>+<br>+More&lt;-list(thDelay=bestDelayb, yy=yyb, xx=xxb,z=zb)<br>+Thresh2&lt;-condiStep(allgammasb, bestThreshb, ninter=ninter, <br>fun=SSRestim2, MoreArgs=More)$newThresh<br>+Thresh3&lt;-condiStep(allgammasb, Thresh2, ninter=ninter, fun=SSRestim2, <br>MoreArgs=More, target=bestThreshb)<br>+SSR2threshb&lt;-Thresh3$SSR<p> #Test statistic<br>-ng*(SSRb-SSRthreshb)/SSRthreshb<br>+<br>+Ftest12b&lt;-as.numeric(nrow(xx)*(SSR